CREATE TABLE workspaces(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,currency CHAR(3) NOT NULL DEFAULT 'YER',status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE branches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,code VARCHAR(30) NOT NULL,is_default TINYINT(1) DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',UNIQUE KEY uq_branch(workspace_id,code),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,username VARCHAR(80) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('owner','manager','supervisor','cashier','system_admin') DEFAULT 'cashier',status ENUM('active','disabled') DEFAULT 'active',last_login DATETIME NULL,UNIQUE KEY uq_login(workspace_id,username),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(140) NOT NULL,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,sku VARCHAR(80) NULL,barcode VARCHAR(100) NULL,unit VARCHAR(30) DEFAULT 'حبة',cost DECIMAL(18,4) DEFAULT 0,price DECIMAL(18,2) DEFAULT 0,alert_qty DECIMAL(18,3) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,UNIQUE KEY uq_sku(workspace_id,sku),UNIQUE KEY uq_barcode(workspace_id,barcode),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(18,3) DEFAULT 0,UNIQUE KEY uq_stock(branch_id,product_id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(50) NOT NULL,cashier_id BIGINT UNSIGNED NOT NULL,subtotal DECIMAL(18,2) NOT NULL,discount DECIMAL(18,2) DEFAULT 0,total DECIMAL(18,2) NOT NULL,paid DECIMAL(18,2) DEFAULT 0,payment_method ENUM('cash','card','transfer') DEFAULT 'cash',status ENUM('completed','void','refunded') DEFAULT 'completed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_invoice(workspace_id,invoice_no),FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(cashier_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sale_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,product_name VARCHAR(190) NOT NULL,quantity DECIMAL(18,3) NOT NULL,unit_price DECIMAL(18,2) NOT NULL,unit_cost DECIMAL(18,4) DEFAULT 0,line_total DECIMAL(18,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE inventory_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,movement_type VARCHAR(30) NOT NULL,quantity DECIMAL(18,3) NOT NULL,reference_id BIGINT UNSIGNED NULL,note VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(60) NULL,entity_id BIGINT UNSIGNED NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,amount DECIMAL(18,2) NOT NULL,expense_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,address VARCHAR(255) NULL,opening_balance DECIMAL(18,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,address VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE purchases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,reference_no VARCHAR(60) NULL,subtotal DECIMAL(18,2) NOT NULL,discount DECIMAL(18,2) DEFAULT 0,total DECIMAL(18,2) NOT NULL,paid DECIMAL(18,2) DEFAULT 0,status ENUM('received','draft','cancelled') DEFAULT 'received',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE purchase_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(18,3) NOT NULL,unit_cost DECIMAL(18,4) NOT NULL,line_total DECIMAL(18,2) NOT NULL,FOREIGN KEY(purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,reference_type ENUM('sale','purchase','expense','customer','supplier') NOT NULL,reference_id BIGINT UNSIGNED NULL,direction ENUM('in','out') NOT NULL,method ENUM('cash','card','transfer','credit') DEFAULT 'cash',amount DECIMAL(18,2) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cash_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,opening_amount DECIMAL(18,2) DEFAULT 0,closing_amount DECIMAL(18,2) NULL,expected_amount DECIMAL(18,2) NULL,status ENUM('open','closed') DEFAULT 'open',opened_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,FOREIGN KEY(workspace_id) REFERENCES workspaces(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
